#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long computeDP(long long n, int x, long long even, long long odd, unordered_map<long long, long long>& dp0, unordered_map<long long, long long>& dp1) {
    if (x == 0) {
        if (dp0.count(n)) {
            return dp0[n];
        }
        if (n == 1) {
            long long res = even;
            dp0[n] = res;
            return res;
        } else if (n == 2) {
            long long res = (even * even + odd * odd) % MOD;
            dp0[n] = res;
            return res;
        }
        long long a = computeDP(n / 2, 0, even, odd, dp0, dp1);
        long long b = computeDP(n - n / 2, 0, even, odd, dp0, dp1);
        long long c = computeDP(n / 2, 1, even, odd, dp0, dp1);
        long long d = computeDP(n - n / 2, 1, even, odd, dp0, dp1);
        long long res = (a * b + c * d) % MOD;
        dp0[n] = res;
        return res;
    } else {
        if (dp1.count(n)) {
            return dp1[n];
        }
        if (n == 1) {
            long long res = odd;
            dp1[n] = res;
            return res;
        } else if (n == 2) {
            long long res = (even * odd + odd * even) % MOD;
            dp1[n] = res;
            return res;
        }
        long long a = computeDP(n / 2, 0, even, odd, dp0, dp1);
        long long b = computeDP(n - n / 2, 1, even, odd, dp0, dp1);
        long long c = computeDP(n / 2, 1, even, odd, dp0, dp1);
        long long d = computeDP(n - n / 2, 0, even, odd, dp0, dp1);
        long long res = (a * b + c * d) % MOD;
        dp1[n] = res;
        return res;
    }
}

long long powMod(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, l, r;
    cin >> n >> m >> l >> r;
    long long totalCells = n * m;
    if (totalCells % 2 == 0) {
        long long rangeSize = r - l + 1;
        long long halfRange = rangeSize / 2;
        if ((rangeSize % 2 == 0) && (l % 2 == 0)) {
            halfRange++;
        }
        long long evenCount = halfRange;
        long long oddCount = rangeSize - evenCount;
        unordered_map<long long, long long> dpZero, dpOne;
        cout << computeDP(totalCells, 0, evenCount, oddCount, dpZero, dpOne) << "\n";
    } else {
        long long answer = powMod(r - l + 1, totalCells);
        cout << answer << "\n";
    }
    return 0;
}

